import { useState, useEffect } from "react";
import { motion, AnimatePresence } from "motion/react";
import { RoomType } from "./types";
import Navigation from "./components/Navigation";
import RoundDoorView from "./components/RoundDoorView";
import WrightRoomView from "./components/WrightRoomView";
import MathomsView from "./components/MathomsView";
import WorldRimView from "./components/WorldRimView";
import AdminView from "./components/AdminView";

// Local imports of cinematic backgrounds generated by the tool
import roundDoorBg from "./assets/images/round_door_bg_1780503259529.png";
import wrightRoomBg from "./assets/images/wright_room_bg_1780503273189.png";
import mathomsBg from "./assets/images/mathoms_bg_1780503285268.png";
import worldRimBg from "./assets/images/world_rim_bg_1780503297632.png";

export default function App() {
  const [activeRoom, setActiveRoom] = useState<RoomType>("door");
  const [isFireActive, setIsFireActive] = useState<boolean>(true);
  const [showAdmin, setShowAdmin] = useState(false);

  const roomsIndex: RoomType[] = ["door", "wright", "mathoms", "world_rim"];
  const currentIndex = roomsIndex.indexOf(activeRoom);
  const isDark = !isFireActive;

  return (
    <div className={`relative w-screen h-screen overflow-hidden font-sans antialiased select-none transition-colors duration-500 ${
      isDark 
        ? "bg-[#080808] text-neutral-100" 
        : "bg-[#F7F5F0] text-stone-800"
    }`}>
      
      {/* Decorative Fireplace Glowing Sparks (Atmospheric Particles) */}
      {isFireActive && (
        <div className="absolute inset-0 pointer-events-none z-20 overflow-hidden mix-blend-screen opacity-70">
          {[...Array(15)].map((_, i) => (
            <motion.div
              key={i}
              className="absolute w-1 md:w-1.5 h-1 md:h-1.5 bg-amber-500 rounded-full blur-[1px]"
              initial={{
                x: `${Math.random() * 100}%`,
                y: "110%",
                opacity: 0.2 + Math.random() * 0.8,
                scale: 0.5 + Math.random() * 1,
              }}
              animate={{
                y: ["110%", "-10%"],
                x: [
                  `${Math.random() * 100}%`,
                  `${Math.random() * 100 + (Math.random() * 20 - 10)}%`,
                ],
                opacity: [0.1, 0.8, 0],
              }}
              transition={{
                duration: 6 + Math.random() * 8,
                repeat: Infinity,
                delay: Math.random() * 8,
                ease: "easeOut",
              }}
            />
          ))}
        </div>
      )}

      {/* Persistent Floating Navigation Header */}
      <Navigation activeRoom={activeRoom} setActiveRoom={setActiveRoom} isFireActive={isFireActive} setIsFireActive={setIsFireActive} onOpenAdmin={() => setShowAdmin(true)} />

      {/* CONTINUOUS CAMERA TRACK (Pans horizontally based on active room) */}
      <motion.div
        animate={{ x: `-${currentIndex * 100}vw` }}
        transition={{ type: "spring", stiffness: 85, damping: 20 }}
        className="flex w-[400vw] h-full"
      >
        {/* ROOM 1: The Round Door (Entrance) */}
        <div className="relative w-screen h-full flex flex-col justify-start pt-28 md:pt-36 px-4 md:px-8 overflow-y-auto scrollbar-thin">
          <div className={`absolute inset-0 z-0 w-full h-full pointer-events-none overflow-hidden transition-colors duration-500 ${isDark ? "bg-neutral-950" : "bg-[#F5F2EB]"}`}>
            {/* Ambient background frame */}
            <img
              referrerPolicy="no-referrer"
              src={roundDoorBg}
              alt="Cozy hobbit entrance"
              className={`w-full h-full object-cover transition-all duration-500 ${isDark ? "opacity-35" : "opacity-[0.14] grayscale-[15%]"}`}
            />
            {/* Cozy warm vignette filter to maintain legibility */}
            <div className={`absolute inset-0 transition-all duration-500 ${isDark ? "bg-radial from-transparent to-neutral-950/90" : "bg-radial from-transparent to-[#F5F2EB]/95"}`} />
          </div>
          
          <div className="relative z-10 w-full flex-grow flex items-center justify-center">
            <RoundDoorView isFireActive={isFireActive} setIsFireActive={setIsFireActive} />
          </div>
        </div>

        {/* ROOM 2: The Wright-room (Workshop) */}
        <div className="relative w-screen h-full flex flex-col justify-start pt-28 md:pt-36 px-4 md:px-8 overflow-y-auto scrollbar-thin">
          <div className={`absolute inset-0 z-0 w-full h-full pointer-events-none overflow-hidden transition-colors duration-500 ${isDark ? "bg-neutral-950" : "bg-[#F5F2EB]"}`}>
            <img
              referrerPolicy="no-referrer"
              src={wrightRoomBg}
              alt="Steampunk creative workshop"
              className={`w-full h-full object-cover transition-all duration-500 ${isDark ? "opacity-35" : "opacity-[0.14] grayscale-[15%]"}`}
              style={{
                filter: `brightness(${isDark ? 1.05 : 0.95})`,
              }}
            />
            <div className={`absolute inset-0 transition-all duration-500 ${isDark ? "bg-radial from-transparent to-neutral-950/90" : "bg-radial from-transparent to-[#F5F2EB]/95"}`} />
          </div>

          <div className="relative z-10 w-full flex-grow flex items-center justify-center">
            <WrightRoomView isFireActive={isFireActive} />
          </div>
        </div>

        {/* ROOM 3: Mathoms (Library Archive) */}
        <div className="relative w-screen h-full flex flex-col justify-start pt-28 md:pt-36 px-4 md:px-8 overflow-y-auto scrollbar-thin">
          <div className={`absolute inset-0 z-0 w-full h-full pointer-events-none overflow-hidden transition-colors duration-500 ${isDark ? "bg-neutral-950" : "bg-[#F5F2EB]"}`}>
            <img
              referrerPolicy="no-referrer"
              src={mathomsBg}
              alt="Hearth library archives"
              className={`w-full h-full object-cover transition-all duration-500 ${isDark ? "opacity-35" : "opacity-[0.14] grayscale-[15%]"}`}
            />
            <div className={`absolute inset-0 transition-all duration-500 ${isDark ? "bg-radial from-transparent to-neutral-950/90" : "bg-radial from-transparent to-[#F5F2EB]/95"}`} />
          </div>

          <div className="relative z-10 w-full flex-grow flex items-center justify-center">
            <MathomsView isFireActive={isFireActive} />
          </div>
        </div>

        {/* ROOM 4: The World-rim (Panoramic Scenic Window) */}
        <div className="relative w-screen h-full flex flex-col justify-start pt-28 md:pt-36 px-4 md:px-8 overflow-y-auto scrollbar-thin">
          <div className={`absolute inset-0 z-0 w-full h-full pointer-events-none overflow-hidden transition-colors duration-500 ${isDark ? "bg-neutral-950" : "bg-[#F5F2EB]"}`}>
            <img
              referrerPolicy="no-referrer"
              src={worldRimBg}
              alt="Circular window looking at rolling green pastures"
              className={`w-full h-full object-cover transition-all duration-500 ${isDark ? "opacity-35" : "opacity-[0.14] grayscale-[15%]"}`}
            />
            <div className={`absolute inset-0 transition-all duration-500 ${isDark ? "bg-radial from-transparent to-neutral-950/90" : "bg-radial from-transparent to-[#F5F2EB]/95"}`} />
          </div>

          <div className="relative z-10 w-full flex-grow flex items-center justify-center">
            <WorldRimView isFireActive={isFireActive} />
          </div>
        </div>
      </motion.div>

      {/* Decorative Outer Border Lines (Aesthetic Pairings) */}
      <div className={`fixed inset-0 pointer-events-none z-40 border transition-colors duration-500 opacity-50 m-2 rounded-2xl ${isDark ? "border-white/5" : "border-stone-400/20"}`} />

      {/* Admin Panel Overlay */}
      <AnimatePresence>
        {showAdmin && <AdminView onClose={() => setShowAdmin(false)} isDark={isDark} />}
      </AnimatePresence>
    </div>
  );
}
